syntax:
template <typename... Types> // Variadic template parameter pack
// or
template <typename T, typename... Rest> // Pack expansion in template parameters
// Non-type parameter pack example:
template <typename T, int... Dims> // Variadic non-type template parameters

code_example:
#include <iostream>
#include <tuple>

template <typename... Types>
class MyTuple {
public:
    std::tuple<Types...> data;
    void print() {
        print_impl(std::index_sequence_for<Types...>{});
    }
private:
    template <std::size_t... Is>
    void print_impl(std::index_sequence<Is...>) {
        ((std::cout << std::get<Is>(data) << ' '), ...);
        std::cout << '\n';
    }
};

int main() {
    MyTuple<int, double, std::string> t{{42, 3.14, "Hello"}};
    t.print();
    return 0;
}
